import{_ as a,o as e,c as r,a2 as t}from"./chunks/framework.CAKCj7G0.js";const g=JSON.parse('{"title":"垃圾回收","description":"","frontmatter":{},"headers":[],"relativePath":"Java/Java/JVM/垃圾回收.md","filePath":"Java/Java/JVM/垃圾回收.md","lastUpdated":1761999543000}'),n={name:"Java/Java/JVM/垃圾回收.md"};function l(i,o,s,p,d,c){return e(),r("div",null,[...o[0]||(o[0]=[t('<h1 id="垃圾回收" tabindex="-1">垃圾回收 <a class="header-anchor" href="#垃圾回收" aria-label="Permalink to &quot;垃圾回收&quot;">​</a></h1><h2 id="一、gc概述-什么是垃圾回收" tabindex="-1">一、GC概述：什么是垃圾回收？ <a class="header-anchor" href="#一、gc概述-什么是垃圾回收" aria-label="Permalink to &quot;一、GC概述：什么是垃圾回收？&quot;">​</a></h2><p>垃圾回收是JVM提供的自动内存管理机制，核心职责是<strong>识别内存中的“垃圾”（即不再被使用的对象）并释放其占用的内存空间</strong>，从而避免内存泄漏、减少手动管理内存的复杂度。</p><p>手动内存管理（如C/C++）需开发者手动分配和释放内存，易出现“忘记释放导致内存泄漏”“重复释放导致崩溃”等问题；JVM的GC机制通过自动化管理解决了这些痛点，但也要求开发者理解其原理以避免内存溢出（OOM）。</p><p>GC的作用范围是JVM内存模型中的<strong>堆内存</strong>和<strong>方法区</strong>（JDK 8后为元空间），因为这两个区域是程序运行时动态分配内存的核心区域，也是“垃圾”产生的主要场所；而程序计数器、虚拟机栈、本地方法栈属于线程私有内存，随线程生命周期自动回收，无需GC参与。</p><h2 id="二、gc核心目标-what-to-do" tabindex="-1">二、GC核心目标：What to Do？ <a class="header-anchor" href="#二、gc核心目标-what-to-do" aria-label="Permalink to &quot;二、GC核心目标：What to Do？&quot;">​</a></h2><p>GC需实现三大核心目标，三者相互制约，不同收集器会根据场景侧重不同目标：</p><ol><li><p><strong>可达性分析：准确识别垃圾</strong>——确保只回收“真正无用”的对象，不误删仍在使用的对象；</p></li><li><p><strong>内存释放：高效回收空间</strong>——将垃圾对象占用的内存释放，供新对象分配使用；</p></li><li><p><strong>内存整理：减少内存碎片</strong>——回收后整理内存空间，避免大量零散空闲空间导致“内存足够但无法分配大对象”的问题。</p></li></ol><h2 id="三、核心流程一-如何识别-垃圾" tabindex="-1">三、核心流程一：如何识别“垃圾”？ <a class="header-anchor" href="#三、核心流程一-如何识别-垃圾" aria-label="Permalink to &quot;三、核心流程一：如何识别“垃圾”？&quot;">​</a></h2><p>GC识别垃圾的核心标准是“对象是否再被使用”，主流实现方式是<strong>可达性分析算法</strong>，替代了早期的“引用计数法”（存在循环引用无法识别的缺陷）。</p><h3 id="_3-1-可达性分析算法" tabindex="-1">3.1 可达性分析算法 <a class="header-anchor" href="#_3-1-可达性分析算法" aria-label="Permalink to &quot;3.1 可达性分析算法&quot;">​</a></h3><p>以“<strong>GC Roots</strong>”为起点，通过引用链遍历内存中的对象：若对象能通过引用链与GC Roots直接或间接相连，则为“可达对象”（仍在使用）；若无法相连，则为“不可达对象”（候选垃圾）。</p><h3 id="_3-2-关键概念-gc-roots" tabindex="-1">3.2 关键概念：GC Roots <a class="header-anchor" href="#_3-2-关键概念-gc-roots" aria-label="Permalink to &quot;3.2 关键概念：GC Roots&quot;">​</a></h3><p>GC Roots是JVM确定的“绝对存活”的引用源，主要包括以下四类：</p><ul><li><p>虚拟机栈（栈帧中的本地变量表）中引用的对象，如方法参数、局部变量；</p></li><li><p>本地方法栈中JNI（Java Native Interface）引用的对象；</p></li><li><p>方法区中类静态属性引用的对象，如<code>static</code>修饰的变量；</p></li><li><p>方法区中常量引用的对象，如<code>final</code>修饰的常量；</p></li><li><p>JVM内部引用，如类加载器、异常对象（<code>Throwable</code>）、系统类等。</p></li></ul><h3 id="_3-3-补充-引用的四种类型" tabindex="-1">3.3 补充：引用的四种类型 <a class="header-anchor" href="#_3-3-补充-引用的四种类型" aria-label="Permalink to &quot;3.3 补充：引用的四种类型&quot;">​</a></h3><p>Java中的引用强度不同，直接影响对象的回收时机，JDK 1.2后将引用分为四级（从强到弱）：</p><table tabindex="0"><thead><tr><th>引用类型</th><th>定义</th><th>回收时机</th><th>典型场景</th></tr></thead><tbody><tr><td>强引用</td><td>默认引用方式，如<code>Object obj = new Object()</code></td><td>仅当引用链断裂时才可能被回收</td><td>普通对象的引用</td></tr><tr><td>软引用</td><td>通过<code>SoftReference</code>类实现</td><td>内存不足时会被回收</td><td>缓存（如图片缓存）</td></tr><tr><td>弱引用</td><td>通过<code>WeakReference</code>类实现</td><td>下一次GC时必被回收（无论内存是否充足）</td><td>临时数据存储（如<code>WeakHashMap</code>）</td></tr><tr><td>虚引用</td><td>通过<code>PhantomReference</code>类实现，又称“幽灵引用”</td><td>无法通过引用获取对象，仅用于监听对象回收事件</td><td>跟踪对象回收（如释放直接内存）</td></tr></tbody></table><h3 id="_3-4-不可达对象的-自救-机会" tabindex="-1">3.4 不可达对象的“自救”机会 <a class="header-anchor" href="#_3-4-不可达对象的-自救-机会" aria-label="Permalink to &quot;3.4 不可达对象的“自救”机会&quot;">​</a></h3><p>不可达对象并非立即被回收，需经历两次标记过程：</p><ol><li><p><strong>第一次标记</strong>：可达性分析后标记为不可达对象，筛选“是否有必要执行<code>finalize()</code>方法”（若对象未重写该方法或已执行过，则无需执行）；</p></li><li><p><strong>第二次标记</strong>：需执行<code>finalize()</code>的对象被放入“F-Queue”队列，由JVM的Finalizer线程执行该方法；若对象在<code>finalize()</code>中重新建立与GC Roots的引用（如赋值给强引用变量），则第二次标记时会被移除出“待回收列表”，实现“自救”。</p></li></ol><p>注意：<code>finalize()</code>方法执行优先级低，且JVM不保证一定执行（如线程被终止），因此不建议通过该方法实现资源释放，推荐使用<code>try-with-resources</code>或手动关闭资源。</p><h2 id="四、核心流程二-垃圾回收算法" tabindex="-1">四、核心流程二：垃圾回收算法 <a class="header-anchor" href="#四、核心流程二-垃圾回收算法" aria-label="Permalink to &quot;四、核心流程二：垃圾回收算法&quot;">​</a></h2><p>垃圾回收算法是GC的核心逻辑，不同算法针对“识别-回收-整理”的实现方式不同，主流算法包括以下四类：</p><h3 id="_4-1-标记-清除算法-mark-sweep" tabindex="-1">4.1 标记-清除算法（Mark-Sweep） <a class="header-anchor" href="#_4-1-标记-清除算法-mark-sweep" aria-label="Permalink to &quot;4.1 标记-清除算法（Mark-Sweep）&quot;">​</a></h3><p>最基础的算法，分为“标记”和“清除”两个阶段：</p><ol><li><p><strong>标记</strong>：通过可达性分析标记所有可达对象；</p></li><li><p><strong>清除</strong>：遍历内存，回收所有未被标记的对象，释放内存空间。</p></li></ol><p><strong>优点</strong>：实现简单，无需移动对象；<strong>缺点</strong>：① 效率低（标记和清除需遍历全量对象）；② 产生大量内存碎片。</p><p>适用场景：内存碎片影响小的场景，如JDK 1.7前的永久代（方法区）回收。</p><h3 id="_4-2-复制算法-copying" tabindex="-1">4.2 复制算法（Copying） <a class="header-anchor" href="#_4-2-复制算法-copying" aria-label="Permalink to &quot;4.2 复制算法（Copying）&quot;">​</a></h3><p>为解决标记-清除的碎片问题，将内存分为“大小相等的两块”（如From区和To区），仅使用其中一块：</p><ol><li><p><strong>标记-复制</strong>：可达性分析后，将From区的可达对象复制到To区，按顺序排列（无碎片）；</p></li><li><p><strong>交换角色</strong>：回收From区所有内存，将From区和To区角色互换，下次GC使用新的From区。</p></li></ol><p><strong>优点</strong>：效率高（仅复制可达对象），无内存碎片；<strong>缺点</strong>：内存利用率低（仅50%），不适合可达对象多的场景（复制成本高）。</p><p>适用场景：可达对象少的区域，如JVM的“新生代”（大多数对象朝生夕死，可达对象少）。</p><h3 id="_4-3-标记-整理算法-mark-compact" tabindex="-1">4.3 标记-整理算法（Mark-Compact） <a class="header-anchor" href="#_4-3-标记-整理算法-mark-compact" aria-label="Permalink to &quot;4.3 标记-整理算法（Mark-Compact）&quot;">​</a></h3><p>针对老年代“对象存活时间长、可达对象多”的特点，在标记-清除基础上增加“整理”阶段：</p><ol><li><p><strong>标记</strong>：同标记-清除算法，标记可达对象；</p></li><li><p><strong>整理</strong>：将所有可达对象向内存一端移动，按顺序排列；</p></li><li><p><strong>清除</strong>：回收内存另一端的所有未标记对象。</p></li></ol><p><strong>优点</strong>：无内存碎片，内存利用率高；<strong>缺点</strong>：增加了“整理”阶段的开销（移动对象+更新引用地址）。</p><p>适用场景：对象存活时间长的区域，如JVM的“老年代”。</p><h3 id="_4-4-分代收集算法-generational-collection" tabindex="-1">4.4 分代收集算法（Generational Collection） <a class="header-anchor" href="#_4-4-分代收集算法-generational-collection" aria-label="Permalink to &quot;4.4 分代收集算法（Generational Collection）&quot;">​</a></h3><p>当前所有商用JVM的默认算法，核心依据“<strong>对象存活周期不同，采用不同回收算法</strong>”，将堆内存分为“新生代”和“老年代”（部分JVM还包含“永久代/元空间”）：</p><ul><li><p><strong>新生代（Young Generation）</strong>：对象创建的区域，特点是“朝生夕死”（90%以上对象创建后很快被回收）。采用“复制算法”，进一步分为Eden区（80%）、From Survivor区（10%）、To Survivor区（10%）： 新对象优先分配到Eden区，当Eden区满时触发“Minor GC”（新生代GC）；</p></li><li><p>Minor GC时，将Eden区和From区的可达对象复制到To区，年龄计数器+1；</p></li><li><p>交换From和To区角色，若对象年龄达到阈值（默认15，可通过<code>-XX:MaxTenuringThreshold</code>调整），则晋升到老年代。</p></li><li><p><strong>老年代（Old Generation）</strong>：存放存活时间长的对象（如新生代晋升的对象、大对象）。特点是“对象存活率高”，采用“标记-整理算法”，当老年代空间不足时触发“Major GC”（老年代GC），Major GC通常伴随Minor GC，开销远大于Minor GC。</p></li><li><p><strong>元空间（Metaspace，JDK 8后）</strong>：替代永久代，存放类元信息、常量、静态变量等，当空间不足时触发“元空间GC”。元空间GC核心采用<strong>标记-清除算法</strong>。由于元空间中类元信息的引用关系相对简单（主要关联类加载器和实例对象），且无用类元信息占比通常较低，标记-清除算法的“内存碎片”问题对元空间影响较小，无需额外整理步骤，可兼顾效率与需求。</p></li></ul><p>大对象处理：超过Eden区一半大小的对象被视为“大对象”，直接分配到老年代（避免在新生代频繁复制），可通过<code>-XX:PretenureSizeThreshold</code>调整阈值。</p><h2 id="五、主流垃圾收集器" tabindex="-1">五、主流垃圾收集器 <a class="header-anchor" href="#五、主流垃圾收集器" aria-label="Permalink to &quot;五、主流垃圾收集器&quot;">​</a></h2><p>垃圾收集器是算法的“具体实现”，不同收集器针对不同场景优化，<strong>JDK 8（LTS版本）的默认垃圾收集器为Parallel收集器（并行收集器）</strong>，同时支持Serial、CMS等收集器，需根据“吞吐量”“响应时间”等需求选择：</p><h3 id="_5-1-serial收集器-串行收集器" tabindex="-1">5.1 Serial收集器（串行收集器） <a class="header-anchor" href="#_5-1-serial收集器-串行收集器" aria-label="Permalink to &quot;5.1  Serial收集器（串行收集器）&quot;">​</a></h3><p>最基础的收集器，采用“串行执行”方式：GC时暂停所有用户线程（“Stop The World，STW”），单线程执行垃圾回收。</p><p><strong>优点</strong>：实现简单、内存占用小、单线程效率高；<strong>缺点</strong>：STW时间长，不适合多核CPU和大型应用。</p><p>适用场景：客户端应用（如桌面程序）、单核CPU环境。</p><p>参数配置：<code>-XX:+UseSerialGC</code>（新生代Serial + 老年代Serial Old）。</p><h3 id="_5-2-parallel收集器-并行收集器" tabindex="-1">5.2 Parallel收集器（并行收集器） <a class="header-anchor" href="#_5-2-parallel收集器-并行收集器" aria-label="Permalink to &quot;5.2  Parallel收集器（并行收集器）&quot;">​</a></h3><p>以“吞吐量优先”为目标，采用“多线程并行回收”，GC时仍会STW，但回收速度更快。</p><p><strong>吞吐量</strong> = 用户线程运行时间 /（用户线程运行时间 + GC时间），Parallel收集器可通过参数调整吞吐量目标。</p><p><strong>优点</strong>：吞吐量高，适合计算密集型应用；<strong>缺点</strong>：STW时间仍较长，不适合响应时间敏感的应用。</p><p>适用场景：服务器端计算密集型应用（如数据分析）。</p><p>参数配置：<code>-XX:+UseParallelGC</code>（<strong>JDK 8</strong> <strong>默认新生代收集器</strong>，搭配老年代Parallel Old收集器）、<code>-XX:MaxGCPauseMillis</code>（最大STW时间，默认无限制）、<code>-XX:GCTimeRatio</code>（吞吐量目标，默认99，即吞吐量≥99%）。</p><h3 id="_5-3-cms收集器-concurrent-mark-sweep" tabindex="-1">5.3 CMS收集器（Concurrent Mark Sweep） <a class="header-anchor" href="#_5-3-cms收集器-concurrent-mark-sweep" aria-label="Permalink to &quot;5.3  CMS收集器（Concurrent Mark Sweep）&quot;">​</a></h3><p>以“响应时间优先”为目标，采用“并发回收”方式，尽可能减少STW时间，核心流程分为四个阶段：</p><ol><li><p><strong>初始标记（STW）</strong>：快速标记GC Roots直接引用的对象，STW时间短；</p></li><li><p><strong>并发标记</strong>：与用户线程并行，遍历引用链标记可达对象；</p></li><li><p><strong>重新标记（STW）</strong>：修正并发标记期间因用户线程操作导致的标记偏差，STW时间比初始标记略长；</p></li><li><p><strong>并发清除</strong>：与用户线程并行，回收未标记对象。</p></li></ol><p><strong>优点</strong>：并发回收，STW时间短，响应性好；</p><p><strong>缺点</strong>：① 内存碎片多（采用标记-清除算法）；② 并发回收占用CPU资源，吞吐量下降；③ 可能出现“Concurrent Mode Failure”（并发回收时老年代满，触发Serial Old收集器，STW时间长）。</p><p>适用场景：响应时间敏感的应用（如Web服务）。</p><p>参数配置：<code>-XX:+UseConcMarkSweepGC</code>（**JDK ** **8支持，JDK ** <strong>9后已标记为废弃</strong>）。</p><h3 id="_5-4-g1收集器-garbage-first" tabindex="-1">5.4 G1收集器（Garbage-First） <a class="header-anchor" href="#_5-4-g1收集器-garbage-first" aria-label="Permalink to &quot;5.4  G1收集器（Garbage-First）&quot;">​</a></h3><p>JDK 9及以后的默认收集器，兼顾“吞吐量”和“响应时间”，核心特点是“区域化分代式回收”。</p><ul><li><p><strong>区域化管理</strong>：将堆内存划分为多个大小相等的“Region”（默认2MB~32MB），每个Region可动态标记为Eden、Survivor、Old、Humongous（大对象区域）；</p></li><li><p><strong>优先回收价值高的Region</strong>：通过统计每个Region的“垃圾占比”和“回收收益”，优先回收收益最高的Region，实现“Garbage-First”；</p></li><li><p><strong>混合回收（Mixed GC）</strong>：不仅回收新生代，还会选择性回收部分老年代Region，减少Major GC的频率。</p></li></ul><p><strong>优点</strong>：兼顾吞吐量和响应时间，支持大堆内存（如几十GB），无内存碎片（Region内采用复制算法，整体采用标记-整理思想）；<strong>缺点</strong>：区域化管理增加了复杂度，小堆内存场景下效率不如Parallel。</p><p>适用场景：大堆内存、响应时间和吞吐量均有要求的应用（如大型Web服务、微服务）。</p><p>参数配置：<code>-XX:+UseG1GC</code>（<strong>JDK 8需手动指定启用</strong> <strong>，JDK 9+</strong> <strong>默认</strong>）、<code>-XX:MaxGCPauseMillis</code>（目标STW时间，默认200ms）。</p><h3 id="_5-5-zgc-shenandoah收集器-低延迟收集器" tabindex="-1">5.5 ZGC/Shenandoah收集器（低延迟收集器） <a class="header-anchor" href="#_5-5-zgc-shenandoah收集器-低延迟收集器" aria-label="Permalink to &quot;5.5  ZGC/Shenandoah收集器（低延迟收集器）&quot;">​</a></h3><p>为超大规模堆内存（如百GB、TB级）设计的低延迟收集器，核心特点是“几乎无STW”（STW时间控制在毫秒级甚至微秒级），通过“着色指针”“读屏障”等技术实现并发标记、并发整理。</p><p><strong>ZGC</strong>：Oracle JDK 11后引入，支持最大16TB堆内存，STW时间≤10ms；<strong>Shenandoah</strong>：OpenJDK专属，JDK 12后引入，设计理念与ZGC类似。</p><p>适用场景：超大规模堆内存、低延迟要求极高的应用（如金融交易、实时计算）。</p><p>参数配置：<strong>JDK 8不支持ZGC和Shenandoah</strong>；ZGC需Oracle JDK 11及以上，用<code>-XX:+UseZGC</code>；Shenandoah需OpenJDK 12及以上，用<code>-XX:+UseShenandoahGC</code>。</p><h2 id="六、gc监控与调优基础" tabindex="-1">六、GC监控与调优基础 <a class="header-anchor" href="#六、gc监控与调优基础" aria-label="Permalink to &quot;六、GC监控与调优基础&quot;">​</a></h2><p>理解GC原理后，需通过监控工具识别问题，再进行调优，核心步骤如下：</p><h3 id="_6-1-核心监控工具" tabindex="-1">6.1 核心监控工具 <a class="header-anchor" href="#_6-1-核心监控工具" aria-label="Permalink to &quot;6.1 核心监控工具&quot;">​</a></h3><ul><li><p><strong>命令行工具</strong>：jps（查看Java进程）、jstat（实时监控GC状态，如<code>jstat -gcutil 进程ID 1000</code>每秒输出GC统计信息）、jmap（生成堆转储快照，如<code>jmap -dump:format=b,file=heap.hprof 进程ID</code>）、jhat（分析堆快照）；</p></li><li><p><strong>可视化工具</strong>：JConsole（JDK自带，简单监控）、VisualVM（功能强大，支持堆分析、GC日志分析）、MAT（Memory Analyzer Tool，专业堆快照分析工具，定位内存泄漏）。</p></li></ul><h3 id="_6-2-调优核心思路" tabindex="-1">6.2 调优核心思路 <a class="header-anchor" href="#_6-2-调优核心思路" aria-label="Permalink to &quot;6.2 调优核心思路&quot;">​</a></h3><ol><li><p><strong>明确目标</strong>：确定是“吞吐量优先”还是“响应时间优先”；</p></li><li><p><strong>监控指标</strong>：关注Minor GC/Major GC频率、STW时间、堆内存使用趋势、吞吐量等；</p></li><li><p><strong>调整参数</strong>：优先调整堆内存大小（<code>-Xms</code>初始堆、<code>-Xmx</code>最大堆，建议设为相同值避免动态调整）、新生代/老年代比例（<code>-XX:NewRatio</code>）、收集器类型等；</p></li><li><p><strong>代码优化</strong>：减少大对象创建、避免内存泄漏（如静态集合持有对象引用、未关闭资源）、合理使用软/弱引用。</p></li></ol><h2 id="七、核心知识点总结" tabindex="-1">七、核心知识点总结 <a class="header-anchor" href="#七、核心知识点总结" aria-label="Permalink to &quot;七、核心知识点总结&quot;">​</a></h2><ul><li><p>GC作用：自动回收堆和元空间的垃圾对象，避免内存泄漏；</p></li><li><p>垃圾识别：基于可达性分析，GC Roots为起点，不可达对象需两次标记；</p></li><li><p>核心算法：分代收集是主流，新生代用复制算法，老年代用标记-整理算法；</p></li><li><p>收集器选择（JDK 8适配）：客户端用Serial，计算密集用默认Parallel，响应敏感用G1（需手动启用）；ZGC/Shenandoah不支持；</p></li><li><p>调优关键：先监控后调优，明确目标，优先调整堆大小和收集器。</p></li></ul><blockquote><p>（注：文档部分内容可能由 AI 生成）</p></blockquote>',83)])])}const u=a(n,[["render",l]]);export{g as __pageData,u as default};
